// 👀 Ce nœud sert uniquement à afficher la structure brute
return {
  json: $json
};

const data = $json;

// =========================
// 1. Récupération du texte du mail
// =========================
let texteMail = data.text || data.textAsHtml || data.html || "";
texteMail = texteMail
  .replace(/<[^>]+>/g, " ")
  .replace(/\s+/g, " ")
  .trim();

// =========================
// 2. Récupération du texte du PDF via OCR
// =========================
let textePDF = "";
try {
  // Vérifie si le résultat OCR existe
  if (data.ParsedResults && data.ParsedResults[0]?.ParsedText) {
    textePDF = data.ParsedResults[0].ParsedText
      .replace(/\\n/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  } else if (data.data) {
    // Fallback au texte déjà présent dans data.data (si OCR non utilisé)
    const parsed = typeof data.data === "string" ? data.data : JSON.stringify(data.data);
    textePDF = parsed.replace(/\s+/g, " ").trim();
  }
} catch (e) {
  textePDF = "";
}

// =========================
// 3. Fusion intelligente
// =========================
const cleanText = [texteMail, textePDF].filter(Boolean).join("\n\n");

// =========================
// 4. Structure enrichie
// =========================
return {
  json: {
    email_source: data.from?.value?.[0]?.address || "",
    client_name: data.from?.value?.[0]?.name || "",
    subject: data.subject || "",
    cleanText,

    context_entreprise: {
      nom: "",
      secteur: "",
      taille: "",
      localisation: "",
      site: ""
    },

    contact_info: {
      nom: data.from?.value?.[0]?.name || "",
      fonction: "",
      langue: "fr",
      niveau_technique: ""
    },

    besoin_implicite: {
      probleme: "",
      priorite: "",
      objectif: ""
    },

    documents_partages: [
      {
        nom: data.attachment_0?.fileName || "Non précisé",
        contenu: textePDF || "Non disponible"
      }
    ]
  }
};

// Récupère les données d'entrée
const data = $json;

// On prend le texte du mail ou du HTML (fallback si texte vide)
let texteSource = data.text || data.textAsHtml || data.html || "";

// Nettoyage : supprime les balises HTML et espaces inutiles
const cleanText = texteSource
  .replace(/<[^>]+>/g, ' ') // supprime le HTML
  .replace(/\s+/g, ' ') // supprime espaces multiples
  .trim();

return {
  json: {
    email_source: data.from?.value?.[0]?.address || '',
    client_name: data.from?.value?.[0]?.name || '',
    subject: data.subject || '',
    cleanText,
  }
};

return items[0].json.results.map(r => ({
  json: {
    title: r.title,
    link: r.link,
    emails: r.emails && r.emails.length ? r.emails.join(", ") : "Aucun",
    phones: r.phones && r.phones.length ? r.phones.join(", ") : "Aucun",
  }
}));

// Import
const pdf = require('pdf-parse');

// Get PDF binary data from previous node (e.g. Gmail)
const pdfData = items[0].binary.attachment_0.data;
const buffer = Buffer.from(pdfData, 'base64');

// Parse the PDF to text
const result = await pdf(buffer);

return [
  {
    json: {
      text: result.text
    }
  }
];
